package medium;public class BalancedBinaryTree{static class TreeNode{int val;TreeNode l,r;TreeNode(int v){val=v;}}public static boolean isBalanced(TreeNode r){return height(r)!=-1;}static int height(TreeNode n){if(n==null)return 0;int lh=height(n.l),rh=height(n.r);if(lh==-1||rh==-1||Math.abs(lh-rh)>1)return -1;return 1+Math.max(lh,rh);}public static void main(String[]args){System.out.println("Balanced works\n");}}
